"""Sparkplug B protocol boundary."""

from __future__ import annotations

import os

# The supplied protobuf file was generated by an older protoc. Selecting the
# pure-Python runtime before importing it preserves compatibility with current
# protobuf releases without pinning the whole application to protobuf 3.20.
os.environ.setdefault("PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION", "python")
